// The loader of /projects/:projectId. It runs when the navigation starts, before any component
// renders, and fills the cache with the project and the board's first page of tasks in parallel,
// so the page appears complete instead of as a row of spinners. A project you can't see, or one
// that doesn't exist, becomes a 404 response that the route's error boundary shows.
import { data, type LoaderFunctionArgs } from "react-router";
import { boardParams, parseTaskFilters, taskQueries } from "@/features/tasks/api";
import { ApiError } from "@/lib/api-client";
import { queryClientContext } from "@/lib/router-context";
import { projectQueries } from "./api";

export async function projectLoader({ params, request, context }: LoaderFunctionArgs) {
  const projectId = Number(params.projectId);
  if (!Number.isInteger(projectId) || projectId < 1) throw data("Project not found", { status: 404 });
  const queryClient = context.get(queryClientContext);
  const filters = parseTaskFilters(new URL(request.url).searchParams);
  try {
    await Promise.all([
      queryClient.ensureQueryData(projectQueries.detail(projectId)),
      queryClient.ensureQueryData(taskQueries.list(projectId, boardParams(filters))),
    ]);
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) throw data("Project not found", { status: 404 });
    throw error;
  }
  return null;
}

// The board's and the list's filters live in the URL's search params, not in state: a filtered
// view survives a reload, can be shared as a link, and the back button undoes a filter. Values at
// their default (sort=due, page=1) stay out of the URL. Changing a filter goes back to page 1.
import { useSearchParams } from "react-router";
import { DEFAULT_FILTERS, parseTaskFilters } from "../api";
import type { TaskFilters } from "../types";

const PARAM: Record<keyof TaskFilters, string> = { status: "status", assignee: "assignee", q: "q", label: "label", sort: "sort", page: "page" };

export function useTaskFilters() {
  const [searchParams, setSearchParams] = useSearchParams();
  const filters = parseTaskFilters(searchParams);
  const activeCount = [filters.status, filters.assignee, filters.q, filters.label].filter((value) => value !== undefined).length;

  /** replace: true changes the URL without a new history entry, for typing in a search box. */
  function setFilter<K extends keyof TaskFilters>(key: K, value: TaskFilters[K] | undefined, { replace = false } = {}) {
    setSearchParams(
      (current) => {
        const next = new URLSearchParams(current);
        if (value === undefined || value === "" || value === DEFAULT_FILTERS[key]) next.delete(PARAM[key]);
        else next.set(PARAM[key], String(value));
        if (key !== "page") next.delete(PARAM.page);
        return next;
      },
      { replace },
    );
  }

  // ...
  return { filters, activeCount, setFilter, clearFilters };
}

// The tasks feature's public API. api.ts and cache.ts may also be imported directly by other
// features: they depend only on lib/, so importing them never pulls in task components.
