// A feature's components and hooks are private: other code imports the feature's index.ts.
// Inside a feature, files import each other with relative paths, so this never stops them.
"no-restricted-imports": [
  "error",
  {
    "patterns": [
      {
        "group": ["@/features/*/components/*", "@/features/*/hooks/*"],
        "message": "Import from the feature's index.ts, its public API."
      }
    ]
  }
]

import { fireEvent, screen, waitFor } from "@testing-library/react";
import { http, HttpResponse } from "msw";
import { expect, test } from "vitest";
import { fixtures, taskById } from "@/test/fixtures";
import { renderWithProviders } from "@/test/render";
import { server } from "@/test/server";
import { TaskCard } from "./components/TaskCard";
import type { Task } from "./types";

const grace = { user_id: 2, name: "Grace Hopper", email: "grace@example.com", role: "member" as const };

function renderCard(taskId: number, { canDelete = false } = {}) {
  const task: Task = { ...taskById(taskId), labels: [] };
  const assignee = task.assignee_id === 2 ? grace : undefined;
  return renderWithProviders(<TaskCard task={task} assignee={assignee} canDelete={canDelete} />);
}

test("the title links to the task", () => {
  renderCard(2);
  expect(screen.getByRole("link", { name: "Write release notes" })).toHaveAttribute("href", "/tasks/2");
});

test("an overdue task says by how much, at the fixed clock", () => {
  renderCard(2);
  expect(screen.getByText("Overdue by 2 days")).toHaveAttribute("datetime", "2026-09-29");
});
// ...
test("Escape closes the menu and returns focus to its button", async () => {
  const { user } = renderCard(7);
  await user.click(screen.getByRole("button", { name: "Status: To do" }));
  expect(screen.getByRole("menu")).toBeInTheDocument();
  await user.keyboard("{Escape}");
  expect(screen.queryByRole("menu")).not.toBeInTheDocument();
  expect(screen.getByRole("button", { name: "Status: To do" })).toHaveFocus();
});

// The Team page: everyone at first, a debounced search, the empty state, and an error with Retry.
import { screen, waitFor } from "@testing-library/react";
import { http, HttpResponse } from "msw";
import { expect, test } from "vitest";
import { renderWithProviders } from "@/test/render";
import { server } from "@/test/server";
import { UserDirectory } from "./UserDirectory";

test("lists everyone before anyone types", async () => {
  renderWithProviders(<UserDirectory />);
  expect(await screen.findByText("Ada Lovelace")).toBeInTheDocument();
  expect(screen.getAllByText(/@example\.com$/)).toHaveLength(4);
});
// ...
test("an error offers Retry, which loads again", async () => {
  server.use(http.get("/v1/users", () => HttpResponse.json({ type: "about:blank", title: "Internal Server Error", status: 500 }, { status: 500 }), { once: true }));
  const { user } = renderWithProviders(<UserDirectory />);
  expect(await screen.findByRole("alert")).toHaveTextContent("Couldn't load the team");
  await user.click(screen.getByRole("button", { name: "Retry" }));
  expect(await screen.findByText("Ada Lovelace")).toBeInTheDocument();
});

// The auth feature: safe redirects after login, the middleware that sends anonymous visitors to
// /login with ?next=, logging in and out. renderApp runs the real routes and middleware against
// the fake API, as the user given in `as` (null: nobody is logged in).
import { screen } from "@testing-library/react";
import { describe, expect, test } from "vitest";
import { renderApp } from "@/test/render";
// ...
test("an anonymous visit goes to the login page and remembers where it was going", async () => {
  const { router } = renderApp("/projects/1", { as: null });
  expect(await screen.findByRole("heading", { name: "Log in to Taskboard" })).toBeInTheDocument();
  expect(router.state.location.pathname).toBe("/login");
  expect(router.state.location.search).toBe("?next=%2Fprojects%2F1");
});
